$done = @{}
Select-String -Path app.log -Pattern '"msg":"x.done"' | ForEach-Object { $done[($_.Line | ConvertFrom-Json).rid] = 1 }
Select-String -Path app.log -Pattern '"msg":"x.start"' | ForEach-Object { $_.Line | ConvertFrom-Json } | Where-Object { -not $done.ContainsKey($_.rid) }

# PowerShell uses .NET regex, which backtracks too:
$re = [regex]'^(a+)+$'
18..24 | ForEach-Object { $s = ('a' * $_) + '!'; '{0} {1:N0} ms' -f $_, (Measure-Command { $re.IsMatch($s) }).TotalMilliseconds }
